FROM DisasterFunds 
GROUP BY disastertype;

results.baseline_sql:
SELECT COUNT(*) 
FROM Students 
WHERE Community IN ('African American', 'Hispanic', 'Native American') AND Program IN ('Computer Science', 'Physics', 'Mathematics');

SELECT MAX(amount) AS max_grant_amount
FROM grants
WHERE department = 'Chemistry';

SELECT month, AVG(species_observed) AS average_species_per_month 
FROM TundraBiologyStudy 
GROUP BY month;

SELECT MAX(ResilienceScore) AS Max_Resilience_Score
FROM Infrastructure
WHERE Location = 'Texas';

SELECT MAX(avg_ph) AS max_avg_ph, MIN(avg_ph) AS min_avg_ph
FROM ocean_acidity;

WITH MaxMinPh AS (
    SELECT MAX(avg_ph) AS max_avg_ph, MIN(avg_ph) AS min_avg_ph
    FROM ocean_acidity
)
SELECT country, avg_ph
FROM ocean_acidity, MaxMinPh
WHERE avg_ph = max_avg_ph OR avg_ph = min_avg_ph;

SELECT SUM(number_of_droughts) AS total_droughts
FROM drought_declarations
WHERE state IN ('Florida', 'New York') AND year BETWEEN 2015 AND 2020;

SELECT state, SUM(spending) AS total_spending
FROM us_conservation
GROUP BY state;

SELECT MAX(size_ha) 
FROM rural_infrastructure_projects 
WHERE country = 'India';

SELECT SUM(budget) AS total_budget
FROM Project_Budget
WHERE state = 'Texas' AND YEAR(start_date) = 2016;

SELECT COUNT(*) 
FROM EmployeeEducation 
WHERE Department = 'Accessibility Services' AND (Degree = 'Master''s' OR Degree = 'Doctorate');

SELECT SUM(amount_spent) AS total_amount_spent
FROM recycling_programs
WHERE location IN ('Australia', 'New Zealand', 'Fiji');

SELECT SUM(weight) AS total_weight 
FROM shipments 
WHERE origin = 'Canada' AND destination = 'United States' AND shipped_at BETWEEN '2021-01-01 00:00:00' AND '2021-01-31 23:59:59';

CREATE TABLE sales (
    id INT,
    feature_id INT,
    quantity INT
);

SELECT AVG(Age) AS AverageAge
FROM Employees
WHERE Department = 'Mining Operations';

SELECT state, AVG(data_usage) AS avg_data_usage
FROM mobile_subscriber_data
GROUP BY state;

SELECT SUM(planting_area) AS total_corn_planted 
FROM crop_planting_2 
WHERE country = 'United States' AND crop = 'Corn';

SELECT country, SUM(cost) AS total_cost 
FROM missions 
GROUP BY country;

SELECT AVG(age) AS average_age
FROM members
WHERE member_region = 'Asia-Pacific';

SELECT COUNT(*) 
FROM agri_innovations 
WHERE introduction_year BETWEEN 2018 AND 2020;

SELECT COUNT(*) 
FROM dance_performances 
WHERE attendee_disability = true AND performance_date >= DATE('now','-6 months');

SELECT DISTINCT destination 
FROM vessel_destinations 
WHERE departure_date BETWEEN '2022-06-01' AND '2022-06-30';

SELECT region, COUNT(DISTINCT donor_name) AS unique_donors
FROM donations
GROUP BY region;
